(async () => {
  try {
    const tc = window.TuquetCrawler;
    const stealthStatus = {
      webdriver: navigator.webdriver,
      hasChrome: !!window.chrome,
      hasPlugins: navigator.plugins.length > 0,
      pluginsCount: navigator.plugins.length
    };
    const crawl = await tc.crawlDocument(document, {
      autoDismissModals: true,
      autoScroll: false,
      extractMetadata: true,
      extractMainContent: true,
      toMarkdown: true
    });
    automaNextBlock({
      success: true,
      stealth: stealthStatus,
      pageType: crawl.pageType,
      title: crawl.metadata?.title,
      hasMarkdown: !!crawl.markdown && crawl.markdown.length > 0,
      markdownPreview: crawl.markdown ? crawl.markdown.slice(0, 150) : '',
      methods: Object.keys(tc)
    });
  } catch (err) {
    automaNextBlock({ $error: true, message: err.message });
  }
})();
